// contracts/user.proto
// Shared Protobuf contract for the Accounts gRPC service.
// Clients and servers deploy independently, so old and new binaries
// can be running side by side in production during a rollout.
syntax = "proto3";

package accounts.v1;

service AccountsService {
  rpc GetUser (GetUserRequest) returns (User);
  rpc UpdateUser (User) returns (User);
}

message GetUserRequest {
  string id = 1;
}

// --- RELEASED baseline ---
// This is what's already shipped: both old clients and old servers
// currently encode/decode User against these exact tag numbers.
//
// message User {
//   string id = 1;
//   string email = 2;
//   string phone = 3;
// }

// --- THIS PR (the diff up for review; CI is green, "it compiles") ---
message User {
  string id = 1;

  // CHANGE A: renamed `email` -> `contactEmail`. Field number `2` is untouched.
  string contactEmail = 2;

  // CHANGE B: dropped `phone` and reused its already-released tag number `3`
  // for a brand-new field of a different type/meaning.
  bool isVerified = 3;
}
